a<-commandArgs(TRUE);if(length(a)<3)stop("Usage: train_lasso_cox.R <dev> <val> <out> [vars] [seed]");if(!requireNamespace("glmnet",quietly=TRUE)||!requireNamespace("survival",quietly=TRUE))stop("Install glmnet and survival");tr<-read.csv(a[1],check.names=FALSE);va<-read.csv(a[2],check.names=FALSE);out<-a[3];v<-if(length(a)>=4)strsplit(a[4],",",TRUE)[[1]]else setdiff(names(tr),c("Time","Event"));seed<-if(length(a)>=5)as.integer(a[5])else 123L;dir.create(out,recursive=TRUE,showWarnings=FALSE);mm<-terms(reformulate(v),data=tr);x<-model.matrix(mm,tr)[,-1,drop=FALSE];xv<-model.matrix(mm,va)[,-1,drop=FALSE];if(!identical(colnames(x),colnames(xv)))stop("Development/validation model-matrix columns differ");set.seed(seed);cv<-glmnet::cv.glmnet(x,survival::Surv(tr$Time,tr$Event),family="cox",alpha=1);for(nm in c("development","validation")){d<-if(nm=="development")tr else va;xx<-if(nm=="development")x else xv;write.csv(data.frame(Time=d$Time,Event=d$Event,Lasso_Cox=as.numeric(predict(cv,newx=xx,s="lambda.min",type="link"))),file.path(out,paste0(nm,"_lasso_cox_predictions.csv")),row.names=FALSE)};saveRDS(list(model=cv,matrix_terms=mm,predictors=v),file.path(out,"lasso_cox_model.rds"))
